<!doctype html>
<html lang="hu" data-theme="dark">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="color-scheme" content="dark light">
  <title>Chat Header Action Bar</title>
  <style>
    :root {
      --color-surface-base: #000000;
      --color-foreground-text: #f5f5f7;
      --color-pure-white: #ffffff;
      --color-pure-white-accent: #ffffff;
      --color-near-black-surface: #09090f;
      --color-near-black-deep: #09090f;
      --color-brand-blue: #0000ff;

      --color-text-muted: color-mix(in srgb, var(--color-foreground-text) 68%, transparent);
      --color-text-subtle: color-mix(in srgb, var(--color-foreground-text) 48%, transparent);
      --color-surface-glass: color-mix(in srgb, var(--color-near-black-surface) 78%, transparent);
      --color-surface-hover: color-mix(in srgb, var(--color-pure-white) 10%, transparent);
      --color-surface-active: color-mix(in srgb, var(--color-brand-blue) 27%, var(--color-near-black-surface));
      --color-surface-elevated: color-mix(in srgb, var(--color-near-black-surface) 92%, var(--color-pure-white) 8%);
      --color-border-subtle: color-mix(in srgb, var(--color-pure-white) 16%, transparent);
      --color-border-strong: color-mix(in srgb, var(--color-pure-white) 28%, transparent);
      --color-focus-ring: color-mix(in srgb, var(--color-brand-blue) 78%, var(--color-pure-white));
      --color-brand-contrast: var(--color-pure-white);

      --font-family-system: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;

      --font-body-default-size: 16px;
      --font-body-default-weight: 400;
      --font-body-secondary-size: 15px;
      --font-body-secondary-weight: 400;
      --font-label-small-size: 11px;
      --font-label-small-weight: 400;
      --font-label-medium-size: 13.5px;
      --font-label-medium-weight: 500;
      --font-nav-title-size: 15px;
      --font-nav-title-weight: 600;
      --font-caption-uppercase-size: 11px;
      --font-caption-uppercase-weight: 600;
      --font-caption-uppercase-tracking: 0.5px;
      --font-message-body-size: 13px;
      --font-message-body-weight: 400;
      --font-message-body-line-height: 19.5px;
      --font-display-heading-size: 20px;
      --font-display-heading-weight: 600;
      --font-body-readable-size: 16px;
      --font-body-readable-weight: 400;
      --font-body-readable-line-height: 23.2px;

      --space-1: 2px;
      --space-2: 2px;
      --space-3: 3px;
      --space-4: 4px;
      --space-5: 5px;
      --space-6: 6px;
      --space-7: 7px;
      --space-8: 8px;
      --space-9: 9px;
      --space-10: 10px;
      --space-11: 11px;
      --space-12: 12px;
      --space-13: 13px;
      --space-14: 14px;
      --space-16: 16px;
      --space-17: 17px;
      --space-20: 20px;
      --space-48: 48px;

      --radius-message-bubble: 18px;
      --radius-input: 16px;
      --radius-button: 23px;

      --icon-sm: 16px;
      --icon-md: 20px;

      --motion-fast: 140ms;
      --motion-standard: 220ms;
      --motion-easing: cubic-bezier(0.2, 0, 0, 1);

      --shadow-action-bar: 0 1px 0 color-mix(in srgb, var(--color-pure-white) 9%, transparent) inset, 0 8px 24px color-mix(in srgb, var(--color-surface-base) 52%, transparent);
      --shadow-control: 0 1px 0 color-mix(in srgb, var(--color-pure-white) 8%, transparent) inset;
      --shadow-elevated: 0 16px 48px color-mix(in srgb, var(--color-surface-base) 68%, transparent), 0 1px 0 color-mix(in srgb, var(--color-pure-white) 9%, transparent) inset;
      --shadow-focus: 0 0 0 var(--space-3) color-mix(in srgb, var(--color-focus-ring) 44%, transparent);
    }

    :root[data-theme="light"] {
      --color-surface-base: #f5f5f7;
      --color-foreground-text: #09090f;
      --color-pure-white: #ffffff;
      --color-pure-white-accent: #ffffff;
      --color-near-black-surface: #ffffff;
      --color-near-black-deep: #ededf1;
      --color-brand-blue: #0000ff;

      --color-text-muted: color-mix(in srgb, var(--color-foreground-text) 66%, transparent);
      --color-text-subtle: color-mix(in srgb, var(--color-foreground-text) 46%, transparent);
      --color-surface-glass: color-mix(in srgb, var(--color-pure-white) 68%, transparent);
      --color-surface-hover: color-mix(in srgb, var(--color-foreground-text) 8%, transparent);
      --color-surface-active: color-mix(in srgb, var(--color-brand-blue) 14%, var(--color-pure-white));
      --color-surface-elevated: color-mix(in srgb, var(--color-pure-white) 94%, var(--color-near-black-deep));
      --color-border-subtle: color-mix(in srgb, var(--color-foreground-text) 15%, transparent);
      --color-border-strong: color-mix(in srgb, var(--color-foreground-text) 26%, transparent);
      --color-focus-ring: var(--color-brand-blue);
      --color-brand-contrast: var(--color-pure-white);
      --shadow-action-bar: 0 1px 0 color-mix(in srgb, var(--color-pure-white) 84%, transparent) inset, 0 8px 24px color-mix(in srgb, var(--color-foreground-text) 11%, transparent);
      --shadow-control: 0 1px 0 color-mix(in srgb, var(--color-pure-white) 85%, transparent) inset;
      --shadow-elevated: 0 16px 48px color-mix(in srgb, var(--color-foreground-text) 18%, transparent), 0 1px 0 color-mix(in srgb, var(--color-pure-white) 84%, transparent) inset;
      --shadow-focus: 0 0 0 var(--space-3) color-mix(in srgb, var(--color-focus-ring) 30%, transparent);
    }

    * {
      box-sizing: border-box;
    }

    html {
      min-width: 320px;
      background: var(--color-surface-base);
      color: var(--color-foreground-text);
      font-family: var(--font-family-system);
    }

    body {
      min-width: 320px;
      min-height: 100vh;
      margin: 0;
      background:
        radial-gradient(circle at 50% 0%, color-mix(in srgb, var(--color-brand-blue) 13%, transparent), transparent 42%),
        var(--color-surface-base);
      color: var(--color-foreground-text);
      font-size: var(--font-body-default-size);
      font-weight: var(--font-body-default-weight);
    }

    button {
      font: inherit;
    }

    button:focus {
      outline: none;
    }

    button:focus-visible {
      outline: var(--space-2) solid var(--color-focus-ring);
      outline-offset: var(--space-2);
      box-shadow: var(--shadow-focus);
    }

    .app-shell {
      min-height: 100vh;
      display: flex;
      flex-direction: column;
    }

    .conversation-header {
      position: sticky;
      top: 0;
      z-index: 10;
      display: flex;
      align-items: center;
      justify-content: space-between;
      min-height: calc(var(--space-48) + var(--space-20));
      padding: var(--space-10) var(--space-12);
      border-bottom: 1px solid var(--color-border-subtle);
      background: color-mix(in srgb, var(--color-surface-base) 74%, transparent);
      backdrop-filter: blur(var(--space-20));
      -webkit-backdrop-filter: blur(var(--space-20));
    }

    .conversation-title {
      min-width: 0;
      display: flex;
      align-items: center;
      gap: var(--space-8);
    }

    .conversation-title__status {
      width: var(--space-8);
      height: var(--space-8);
      flex: 0 0 auto;
      border-radius: var(--radius-button);
      background: var(--color-brand-blue);
      box-shadow: 0 0 0 var(--space-4) color-mix(in srgb, var(--color-brand-blue) 18%, transparent);
    }

    .conversation-title__text {
      overflow: hidden;
      color: var(--color-foreground-text);
      font-size: var(--font-nav-title-size);
      font-weight: var(--font-nav-title-weight);
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .header-actions {
      position: relative;
      display: flex;
      flex: 0 0 auto;
      align-items: center;
      justify-content: center;
      gap: var(--space-1);
      padding: var(--space-4);
      border: 1px solid var(--color-border-subtle);
      border-radius: var(--radius-button);
      background: var(--color-surface-glass);
      box-shadow: var(--shadow-action-bar);
      backdrop-filter: blur(var(--space-20)) saturate(145%);
      -webkit-backdrop-filter: blur(var(--space-20)) saturate(145%);
    }

    .icon-button {
      appearance: none;
      display: inline-grid;
      width: 36px;
      height: 36px;
      place-items: center;
      flex: 0 0 auto;
      margin: 0;
      padding: 0;
      border: 1px solid transparent;
      border-radius: var(--radius-button);
      background: transparent;
      color: var(--color-foreground-text);
      cursor: pointer;
      box-shadow: var(--shadow-control);
      transition:
        background-color var(--motion-fast) var(--motion-easing),
        border-color var(--motion-fast) var(--motion-easing),
        color var(--motion-fast) var(--motion-easing),
        transform var(--motion-fast) var(--motion-easing),
        box-shadow var(--motion-fast) var(--motion-easing);
    }

    .icon-button:hover {
      border-color: var(--color-border-subtle);
      background: var(--color-surface-hover);
    }

    .icon-button:active {
      background: var(--color-surface-active);
      color: var(--color-brand-contrast);
      transform: scale(0.94);
    }

    .icon-button[aria-expanded="true"],
    .icon-button[aria-pressed="true"] {
      border-color: color-mix(in srgb, var(--color-brand-blue) 60%, var(--color-border-subtle));
      background: var(--color-surface-active);
      color: var(--color-brand-contrast);
    }

    .icon-button:disabled {
      opacity: 0.42;
      cursor: not-allowed;
      pointer-events: none;
    }

    .icon {
      width: var(--icon-sm);
      height: var(--icon-sm);
      display: block;
      fill: none;
      stroke: currentColor;
      stroke-linecap: round;
      stroke-linejoin: round;
      stroke-width: 1.8;
    }

    .action-popover {
      position: absolute;
      top: calc(100% + var(--space-8));
      right: 0;
      z-index: 20;
      width: min(280px, calc(100vw - var(--space-20)));
      padding: var(--space-6);
      border: 1px solid var(--color-border-strong);
      border-radius: var(--radius-input);
      background: var(--color-surface-elevated);
      box-shadow: var(--shadow-elevated);
      backdrop-filter: blur(var(--space-20)) saturate(145%);
      -webkit-backdrop-filter: blur(var(--space-20)) saturate(145%);
    }

    .action-popover[hidden] {
      display: none;
    }

    .action-menu {
      display: grid;
      gap: var(--space-3);
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .menu-item {
      display: flex;
      width: 100%;
      min-height: 40px;
      align-items: center;
      gap: var(--space-10);
      padding: var(--space-8) var(--space-10);
      border: 1px solid transparent;
      border-radius: var(--radius-input);
      background: transparent;
      color: var(--color-foreground-text);
      cursor: pointer;
      text-align: left;
      transition:
        background-color var(--motion-fast) var(--motion-easing),
        border-color var(--motion-fast) var(--motion-easing),
        color var(--motion-fast) var(--motion-easing);
    }

    .menu-item:hover,
    .menu-item:focus-visible {
      border-color: var(--color-border-subtle);
      background: var(--color-surface-hover);
    }

    .menu-item:active {
      background: var(--color-surface-active);
    }

    .menu-item__icon {
      width: var(--icon-sm);
      height: var(--icon-sm);
      flex: 0 0 auto;
      color: var(--color-text-muted);
    }

    .menu-item__label {
      font-size: var(--font-label-medium-size);
      font-weight: var(--font-label-medium-weight);
    }

    .dialog-backdrop {
      position: fixed;
      inset: 0;
      z-index: 30;
      display: grid;
      place-items: center;
      padding: var(--space-16);
      background: color-mix(in srgb, var(--color-surface-base) 58%, transparent);
      backdrop-filter: blur(var(--space-8));
      -webkit-backdrop-filter: blur(var(--space-8));
    }

    .dialog-backdrop[hidden] {
      display: none;
    }

    .files-dialog {
      width: min(520px, 100%);
      max-height: min(680px, calc(100vh - var(--space-48)));
      overflow: auto;
      border: 1px solid var(--color-border-strong);
      border-radius: var(--radius-message-bubble);
      background: var(--color-surface-elevated);
      box-shadow: var(--shadow-elevated);
    }

    .files-dialog__header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: var(--space-12);
      padding: var(--space-14) var(--space-16);
      border-bottom: 1px solid var(--color-border-subtle);
    }

    .files-dialog__title {
      margin: 0;
      color: var(--color-foreground-text);
      font-size: var(--font-display-heading-size);
      font-weight: var(--font-display-heading-weight);
    }

    .files-dialog__close {
      width: 36px;
      height: 36px;
    }

    .files-dialog__body {
      display: grid;
      gap: var(--space-12);
      padding: var(--space-16);
    }

    .files-dialog__description {
      margin: 0;
      color: var(--color-text-muted);
      font-size: var(--font-body-secondary-size);
      font-weight: var(--font-body-secondary-weight);
      line-height: var(--font-body-readable-line-height);
    }

    .source-list {
      display: grid;
      gap: var(--space-8);
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .source-list__item {
      display: flex;
      align-items: center;
      gap: var(--space-10);
      min-height: var(--space-48);
      padding: var(--space-10);
      border: 1px solid var(--color-border-subtle);
      border-radius: var(--radius-input);
      background: color-mix(in srgb, var(--color-surface-base) 34%, transparent);
    }

    .source-list__badge {
      display: grid;
      width: 32px;
      height: 32px;
      place-items: center;
      flex: 0 0 auto;
      border-radius: var(--radius-button);
      background: color-mix(in srgb, var(--color-brand-blue) 18%, transparent);
      color: var(--color-brand-contrast);
    }

    .source-list__copy {
      min-width: 0;
    }

    .source-list__name {
      display: block;
      overflow: hidden;
      color: var(--color-foreground-text);
      font-size: var(--font-label-medium-size);
      font-weight: var(--font-label-medium-weight);
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .source-list__meta {
      display: block;
      margin-top: var(--space-3);
      color: var(--color-text-subtle);
      font-size: var(--font-label-small-size);
      font-weight: var(--font-label-small-weight);
    }

    .main-content {
      flex: 1;
      display: grid;
      place-items: center;
      padding: var(--space-48) var(--space-16);
    }

    .empty-state {
      max-width: 520px;
      text-align: center;
    }

    .empty-state__eyebrow {
      margin: 0 0 var(--space-8);
      color: var(--color-brand-blue);
      font-size: var(--font-caption-uppercase-size);
      font-weight: var(--font-caption-uppercase-weight);
      letter-spacing: var(--font-caption-uppercase-tracking);
      text-transform: uppercase;
    }

    .empty-state__heading {
      margin: 0;
      color: var(--color-foreground-text);
      font-size: var(--font-display-heading-size);
      font-weight: var(--font-display-heading-weight);
    }

    .empty-state__body {
      margin: var(--space-12) 0 0;
      color: var(--color-text-muted);
      font-size: var(--font-body-readable-size);
      font-weight: var(--font-body-readable-weight);
      line-height: var(--font-body-readable-line-height);
    }

    .theme-toggle {
      position: fixed;
      right: var(--space-16);
      bottom: var(--space-16);
      display: inline-flex;
      min-height: 36px;
      align-items: center;
      gap: var(--space-8);
      padding: var(--space-8) var(--space-12);
      border: 1px solid var(--color-border-subtle);
      border-radius: var(--radius-button);
      background: var(--color-surface-glass);
      color: var(--color-foreground-text);
      box-shadow: var(--shadow-action-bar);
      cursor: pointer;
      backdrop-filter: blur(var(--space-20));
      -webkit-backdrop-filter: blur(var(--space-20));
      font-size: var(--font-label-medium-size);
      font-weight: var(--font-label-medium-weight);
    }

    .theme-toggle:hover {
      background: var(--color-surface-hover);
    }

    @media (min-width: 480px) {
      .conversation-header {
        padding-right: var(--space-16);
        padding-left: var(--space-16);
      }
    }

    @media (min-width: 768px) {
      .header-actions {
        gap: var(--space-2);
        padding: var(--space-5);
      }

      .icon-button {
        width: 40px;
        height: 40px;
      }

      .icon,
      .menu-item__icon {
        width: var(--icon-md);
        height: var(--icon-md);
      }

      .menu-item {
        min-height: 44px;
      }

      .files-dialog__close {
        width: 40px;
        height: 40px;
      }
    }

    @media (min-width: 1024px) {
      .conversation-header {
        padding-right: var(--space-20);
        padding-left: var(--space-20);
      }

      .header-actions {
        gap: var(--space-3);
        padding: var(--space-6);
      }

      .icon-button {
        width: 44px;
        height: 44px;
      }

      .icon-button:hover {
        border-color: var(--color-border-strong);
        background: color-mix(in srgb, var(--color-surface-hover) 88%, var(--color-brand-blue) 12%);
        box-shadow: var(--shadow-control), 0 5px 16px color-mix(in srgb, var(--color-brand-blue) 13%, transparent);
        transform: translateY(-1px);
      }

      .icon-button:active {
        transform: translateY(0) scale(0.95);
      }

      .files-dialog__close {
        width: 44px;
        height: 44px;
      }
    }

    @media (max-width: 767px) {
      .share-control {
        display: none;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }
  </style>
</head>
<body>
  <div class="app-shell" id="app-shell">
    <header class="conversation-header">
      <div class="conversation-title">
        <span class="conversation-title__status" aria-hidden="true"></span>
        <span class="conversation-title__text">Új beszélgetés</span>
      </div>

      <div class="header-actions" aria-label="Beszélgetési műveletek">
        <button class="icon-button" id="new-chat-button" type="button" aria-label="Új csevegés">
          <svg class="icon" viewBox="0 0 24 24" aria-hidden="true">
            <path d="M12 5v14"></path>
            <path d="M5 12h14"></path>
          </svg>
        </button>

        <button class="icon-button share-control" id="share-chat-button" type="button" aria-label="Csevegés megosztása">
          <svg class="icon" viewBox="0 0 24 24" aria-hidden="true">
            <circle cx="18" cy="5.5" r="2.5"></circle>
            <circle cx="6" cy="12" r="2.5"></circle>
            <circle cx="18" cy="18.5" r="2.5"></circle>
            <path d="m8.2 10.8 7.6-4.1"></path>
            <path d="m8.2 13.2 7.6 4.1"></path>
          </svg>
        </button>

        <button class="icon-button" id="more-options-button" type="button" aria-label="További lehetőségek" aria-haspopup="menu" aria-expanded="false" aria-controls="more-options-menu">
          <svg class="icon" viewBox="0 0 24 24" aria-hidden="true">
            <circle cx="5" cy="12" r="1.2" fill="currentColor" stroke="none"></circle>
            <circle cx="12" cy="12" r="1.2" fill="currentColor" stroke="none"></circle>
            <circle cx="19" cy="12" r="1.2" fill="currentColor" stroke="none"></circle>
          </svg>
        </button>

        <button class="icon-button" id="files-sources-button" type="button" aria-label="Fájlok és források" aria-haspopup="dialog" aria-expanded="false" aria-pressed="false" aria-controls="files-dialog">
          <svg class="icon" viewBox="0 0 24 24" aria-hidden="true">
            <path d="M14 3.5H6.5A2.5 2.5 0 0 0 4 6v12a2.5 2.5 0 0 0 2.5 2.5h11A2.5 2.5 0 0 0 20 18v-9.5Z"></path>
            <path d="M14 3.5V9h6"></path>
            <path d="M8 13h8"></path>
            <path d="M8 16.5h5"></path>
          </svg>
        </button>

        <div class="action-popover" id="more-options-menu" role="menu" aria-label="További lehetőségek" hidden>
          <ul class="action-menu">
            <li role="none">
              <button class="menu-item" type="button" role="menuitem" data-menu-action="rename">
                <svg class="menu-item__icon" viewBox="0 0 24 24" aria-hidden="true">
                  <path d="m4 16.5-.5 4 4-.5L18.7 8.8a2.1 2.1 0 0 0-3-3Z"></path>
                  <path d="m14.2 5.3 4.5 4.5"></path>
                </svg>
                <span class="menu-item__label">Beszélgetés átnevezése</span>
              </button>
            </li>
            <li role="none">
              <button class="menu-item" type="button" role="menuitem" data-menu-action="archive">
                <svg class="menu-item__icon" viewBox="0 0 24 24" aria-hidden="true">
                  <path d="M4 8h16"></path>
                  <path d="M6.5 8V19.5h11V8"></path>
                  <path d="M9 11.5h6"></path>
                  <path d="M8 4.5h8l1 3.5H7Z"></path>
                </svg>
                <span class="menu-item__label">Beszélgetés archiválása</span>
              </button>
            </li>
            <li role="none">
              <button class="menu-item" type="button" role="menuitem" data-menu-action="theme">
                <svg class="menu-item__icon" viewBox="0 0 24 24" aria-hidden="true">
                  <path d="M20.5 14.2A8.5 8.5 0 1 1 9.8 3.5a6.7 6.7 0 0 0 10.7 10.7Z"></path>
                </svg>
                <span class="menu-item__label">Téma váltása</span>
              </button>
            </li>
          </ul>
        </div>
      </div>
    </header>

