    }

    .menu-item:hover,
    .menu-item:focus-visible {
      border-color: var(--border-subtle);
      background: var(--surface-hover);
    }

    .menu-item:active {
      background: var(--surface-active);
    }

    .menu-item__icon {
      width: var(--icon-sm);
      height: var(--icon-sm);
      flex: 0 0 auto;
      color: var(--color-text-muted);
    }

    .menu-item__label {
      font-size: var(--font-label-medium-size);
      font-weight: var(--font-label-medium-weight);
    }

    .dialog-backdrop {
      position: fixed;
      inset: 0;
      z-index: 30;
      display: grid;
      place-items: center;
      padding: var(--space-16);
      background: color-mix(in srgb, var(--surface-base) 58%, transparent);
      backdrop-filter: blur(var(--space-8));
      -webkit-backdrop-filter: blur(var(--space-8));
    }

    .files-dialog {
      width: min(520px, 100%);
      max-height: min(680px, calc(100vh - var(--space-48)));
      overflow: auto;
      border: 1px solid var(--border-strong);
      border-radius: var(--radius-message-bubble);
      background: var(--surface-elevated);
      box-shadow: var(--shadow-elevated);
    }

    .files-dialog__header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: var(--space-12);
      padding: var(--space-14) var(--space-16);
      border-bottom: 1px solid var(--border-subtle);
    }

    .files-dialog__title {
      margin: 0;
      color: var(--color-foreground-text);
      font-size: var(--font-display-heading-size);
      font-weight: var(--font-display-heading-weight);
    }

    .files-dialog__close {
      width: 36px;
      height: 36px;
    }

    .files-dialog__body {
      display: grid;
      gap: var(--space-12);
      padding: var(--space-16);
    }

    .files-dialog__description {
      margin: 0;
      color: var(--color-text-muted);
      font-size: var(--font-body-secondary-size);
      font-weight: var(--font-body-secondary-weight);
      line-height: var(--font-body-readable-line-height);
    }

    .source-list {
      display: grid;
      gap: var(--space-8);
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .source-list__item {
      display: flex;
      min-height: var(--space-48);
      align-items: center;
      gap: var(--space-10);
      padding: var(--space-10);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-input);
      background: color-mix(in srgb, var(--surface-base) 34%, transparent);
    }

    .source-list__badge {
      display: grid;
      width: 32px;
      height: 32px;
      flex: 0 0 auto;
      place-items: center;
      border-radius: var(--radius-button);
      background: color-mix(in srgb, var(--color-brand-blue) 18%, transparent);
      color: var(--brand-contrast);
    }

    .source-list__copy {
      min-width: 0;
    }

    .source-list__name {
      display: block;
      overflow: hidden;
      color: var(--color-foreground-text);
      font-size: var(--font-label-medium-size);
      font-weight: var(--font-label-medium-weight);
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .source-list__meta {
      display: block;
      margin-top: var(--space-3);
      color: var(--color-text-subtle);
      font-size: var(--font-label-small-size);
      font-weight: var(--font-label-small-weight);
    }

    .main-content {
      display: grid;
      flex: 1;
      place-items: center;
      padding: var(--space-48) var(--space-16);
    }

    .empty-state {
      max-width: 520px;
      text-align: center;
    }

    .empty-state__eyebrow {
      margin: 0 0 var(--space-8);
      color: var(--color-brand-blue);
      font-size: var(--font-caption-uppercase-size);
      font-weight: var(--font-caption-uppercase-weight);
      letter-spacing: var(--font-caption-uppercase-tracking);
      text-transform: uppercase;
    }

    .empty-state__heading {
      margin: 0;
      color: var(--color-foreground-text);
      font-size: var(--font-display-heading-size);
      font-weight: var(--font-display-heading-weight);
    }

    .empty-state__body {
      margin: var(--space-12) 0 0;
      color: var(--color-text-muted);
      font-size: var(--font-body-readable-size);
      font-weight: var(--font-body-readable-weight);
      line-height: var(--font-body-readable-line-height);
    }

    .theme-toggle {
      position: fixed;
      right: var(--space-16);
      bottom: var(--space-16);
      display: inline-flex;
      min-height: 36px;
      align-items: center;
      gap: var(--space-8);
      padding: var(--space-8) var(--space-12);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-button);
      background: var(--surface-glass);
      color: var(--color-foreground-text);
      box-shadow: var(--shadow-action-bar);
      cursor: pointer;
      backdrop-filter: blur(var(--space-20));
      -webkit-backdrop-filter: blur(var(--space-20));
      font-size: var(--font-label-medium-size);
      font-weight: var(--font-label-medium-weight);
    }

    .theme-toggle:hover {
      background: var(--surface-hover);
    }

    @media (min-width: 480px) {
      .conversation-header {
        padding-right: var(--space-16);
        padding-left: var(--space-16);
      }
    }

    @media (max-width: 767px) {
      .share-control {
        display: none;
      }
    }

    @media (min-width: 768px) {
      .header-actions {
        gap: var(--space-2);
        padding: var(--space-5);
      }

      .icon-button {
        width: 40px;
        height: 40px;
      }

      .icon,
      .menu-item__icon {
        width: var(--icon-md);
        height: var(--icon-md);
      }

      .menu-item {
        min-height: 44px;
      }

      .files-dialog__close {
        width: 40px;
        height: 40px;
      }
    }

    @media (min-width: 1024px) {
      .conversation-header {
        padding-right: var(--space-20);
        padding-left: var(--space-20);
      }

      .header-actions {
        gap: var(--space-3);
        padding: var(--space-6);
      }

      .icon-button {
        width: 44px;
        height: 44px;
      }

      .icon-button:hover {
        border-color: var(--border-strong);
        background: color-mix(in srgb, var(--surface-hover) 88%, var(--color-brand-blue) 12%);
        box-shadow: var(--shadow-control), 0 5px 16px color-mix(in srgb, var(--color-brand-blue) 13%, transparent);
        transform: translateY(-1px);
      }

      .icon-button:active {
        transform: translateY(0) scale(0.95);
      }

      .files-dialog__close {
        width: 44px;
        height: 44px;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }
  </style>
</head>
<body>
  <div class="app-shell" id="app-shell">
    <header class="conversation-header">
      <div class="conversation-title">
        <span class="conversation-title__status" aria-hidden="true"></span>
        <span class="conversation-title__text" id="conversation-title">Új beszélgetés</span>
      </div>

      <div class="header-actions" aria-label="Beszélgetési műveletek">
        <button class="icon-button" id="new-chat-button" type="button" aria-label="Új csevegés">
          <svg class="icon" viewBox="0 0 24 24" aria-hidden="true">
            <path d="M12 5v14"></path>
            <path d="M5 12h14"></path>
          </svg>
        </button>

        <button class="icon-button share-control" id="share-chat-button" type="button" aria-label="Csevegés megosztása">
          <svg class="icon" viewBox="0 0 24 24" aria-hidden="true">
            <circle cx="18" cy="5.5" r="2.5"></circle>
            <circle cx="6" cy="12" r="2.5"></circle>
            <circle cx="18" cy="18.5" r="2.5"></circle>
            <path d="m8.2 10.8 7.6-4.1"></path>
            <path d="m8.2 13.2 7.6 4.1"></path>
          </svg>
        </button>

        <button class="icon-button" id="more-options-button" type="button" aria-label="További lehetőségek" aria-haspopup="menu" aria-expanded="false" aria-controls="more-options-menu">
          <svg class="icon" viewBox="0 0 24 24" aria-hidden="true">
            <circle cx="5" cy="12" r="1.2" fill="currentColor" stroke="none"></circle>
            <circle cx="12" cy="12" r="1.2" fill="currentColor" stroke="none"></circle>
            <circle cx="19" cy="12" r="1.2" fill="currentColor" stroke="none"></circle>
          </svg>
        </button>

        <button class="icon-button" id="files-sources-button" type="button" aria-label="Fájlok és források" aria-haspopup="dialog" aria-expanded="false" aria-pressed="false" aria-controls="files-dialog">
          <svg class="icon" viewBox="0 0 24 24" aria-hidden="true">
            <path d="M14 3.5H6.5A2.5 2.5 0 0 0 4 6v12a2.5 2.5 0 0 0 2.5 2.5h11A2.5 2.5 0 0 0 20 18v-9.5Z"></path>
            <path d="M14 3.5V9h6"></path>
            <path d="M8 13h8"></path>
            <path d="M8 16.5h5"></path>
          </svg>
        </button>

        <div class="action-popover" id="more-options-menu" role="menu" aria-label="További lehetőségek" hidden>
          <ul class="action-menu">
            <li role="none">
              <button class="menu-item" type="button" role="menuitem" data-menu-action="rename">
                <svg class="menu-item__icon" viewBox="0 0 24 24" aria-hidden="true">
                  <path d="m4 16.5-.5 4 4-.5L18.7 8.8a2.1 2.1 0 0 0-3-3Z"></path>
                  <path d="m14.2 5.3 4.5 4.5"></path>
                </svg>
                <span class="menu-item__label">Beszélgetés átnevezése</span>
              </button>
            </li>
            <li role="none">
              <button class="menu-item" type="button" role="menuitem" data-menu-action="archive">
                <svg class="menu-item__icon" viewBox="0 0 24 24" aria-hidden="true">
                  <path d="M4 8h16"></path>
                  <path d="M6.5 8V19.5h11V8"></path>
                  <path d="M9 11.5h6"></path>
                  <path d="M8 4.5h8l1 3.5H7Z"></path>
                </svg>
                <span class="menu-item__label">Beszélgetés archiválása</span>
              </button>
            </li>
            <li role="none">
              <button class="menu-item" type="button" role="menuitem" data-menu-action="theme">
                <svg class="menu-item__icon" viewBox="0 0 24 24" aria-hidden="true">
                  <path d="M20.5 14.2A8.5 8.5 0 1 1 9.8 3.5a6.7 6.7 0 0 0 10.7 10.7Z"></path>
                </svg>
                <span class="menu-item__label">Téma váltása</span>
              </button>
            </li>
          </ul>
        </div>
      </div>
    </header>

    <main class="main-content" id="main-content">
      <section class="empty-state" aria-labelledby="empty-state-heading">
        <p class="empty-state__eyebrow">Csevegés</p>
        <h1 class="empty-state__heading" id="empty-state-heading">Mire vagy kíváncsi?</h1>
        <p class="empty-state__body">Indíts új beszélgetést, oszd meg ezt a csevegést, vagy tekintsd meg a kapcsolódó fájlokat és forrásokat.</p>
      </section>
    </main>
  </div>

  <div class="dialog-backdrop" id="files-backdrop" hidden>
    <section class="files-dialog" id="files-dialog" role="dialog" aria-modal="true" aria-labelledby="files-dialog-title" aria-describedby="files-dialog-description">
      <header class="files-dialog__header">
        <h2 class="files-dialog__title" id="files-dialog-title">Fájlok és források</h2>
        <button class="icon-button files-dialog__close" id="close-files-dialog-button" type="button" aria-label="Fájlok és források panel bezárása">
          <svg class="icon" viewBox="0 0 24 24" aria-hidden="true">
            <path d="m6 6 12 12"></path>
            <path d="m18 6-12 12"></path>
          </svg>
        </button>
      </header>

      <div class="files-dialog__body">
        <p class="files-dialog__description" id="files-dialog-description">A beszélgetéshez kapcsolódó források és feltöltött fájlok itt érhetők el.</p>

        <ul class="source-list" aria-label="Kapcsolódó források">
          <li class="source-list__item">
            <span class="source-list__badge" aria-hidden="true">
              <svg class="icon" viewBox="0 0 24 24">
                <path d="M14 3.5H6.5A2.5 2.5 0 0 0 4 6v12a2.5 2.5 0 0 0 2.5 2.5h11A2.5 2.5 0 0 0 20 18v-9.5Z"></path>
                <path d="M14 3.5V9h6"></path>
              </svg>
            </span>
            <span class="source-list__copy">
              <span class="source-list__name">Beszélgetési kontextus</span>
              <span class="source-list__meta">Rendszerforrás</span>
            </span>
          </li>

          <li class="source-list__item">
            <span class="source-list__badge" aria-hidden="true">
              <svg class="icon" viewBox="0 0 24 24">
                <path d="M8 12h8"></path>
                <path d="M12 8v8"></path>
                <circle cx="12" cy="12" r="8.5"></circle>
              </svg>
            </span>
            <span class="source-list__copy">
              <span class="source-list__name">Új forrás hozzáadása</span>
              <span class="source-list__meta">Fájl vagy hivatkozás csatolása</span>
            </span>
          </li>
        </ul>
      </div>
    </section>
  </div>

  <button class="theme-toggle" id="theme-toggle" type="button" aria-label="Világos téma bekapcsolása" aria-pressed="false">
    <svg class="icon" viewBox="0 0 24 24" aria-hidden="true">
      <circle cx="12" cy="12" r="3.5"></circle>
      <path d="M12 2.5v2"></path>
      <path d="M12 19.5v2"></path>
      <path d="m5.3 5.3 1.4 1.4"></path>
      <path d="m17.3 17.3 1.4 1.4"></path>
      <path d="M2.5 12h2"></path>
      <path d="M19.5 12h2"></path>
      <path d="m5.3 18.7 1.4-1.4"></path>
      <path d="m17.3 6.7 1.4-1.4"></path>
    </svg>
    <span>Téma</span>
  </button>

  <script>
    (() => {
      const root = document.documentElement;
      const appShell = document.getElementById("app-shell");
      const conversationTitle = document.getElementById("conversation-title");
      const emptyStateHeading = document.getElementById("empty-state-heading");
      const newChatButton = document.getElementById("new-chat-button");
      const shareChatButton = document.getElementById("share-chat-button");
      const moreOptionsButton = document.getElementById("more-options-button");
      const moreOptionsMenu = document.getElementById("more-options-menu");
      const filesSourcesButton = document.getElementById("files-sources-button");
      const filesBackdrop = document.getElementById("files-backdrop");
      const filesDialog = document.getElementById("files-dialog");
      const closeFilesDialogButton = document.getElementById("close-files-dialog-button");
      const themeToggle = document.getElementById("theme-toggle");
      const menuItems = Array.from(moreOptionsMenu.querySelectorAll('[role="menuitem"]'));
      let menuOpen = false;
      let dialogOpen = false;
      let menuTrigger = null;
      let dialogTrigger = null;

      const getFocusableElements = (container) => {
        return Array.from(
          container.querySelectorAll(
            'a[href], area[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
          )
        ).filter((element) => !element.hidden && element.getClientRects().length > 0);
      };

      const syncThemeControl = () => {
        const isLight = root.dataset.theme === "light";
        themeToggle.setAttribute("aria-pressed", String(isLight));
        themeToggle.setAttribute("aria-label", isLight ? "Sötét téma bekapcsolása" : "Világos téma bekapcsolása");
      };

      const setTheme = (theme) => {
        root.dataset.theme = theme;
        try {
          window.localStorage.setItem("chat-header-theme", theme);
        } catch (error) {
          root.dataset.theme = theme;
        }
        syncThemeControl();
      };

      const closeMenu = (restoreFocus) => {
        if (!menuOpen) {
          return;
        }

        menuOpen = false;
        moreOptionsMenu.hidden = true;
        moreOptionsButton.setAttribute("aria-expanded", "false");

        if (restoreFocus && menuTrigger) {
          menuTrigger.focus();
        }

        menuTrigger = null;
      };

      const openMenu = (focusLast) => {
        if (dialogOpen) {
          closeDialog(false);
        }

        menuOpen = true;
        menuTrigger = moreOptionsButton;
        moreOptionsMenu.hidden = false;
        moreOptionsButton.setAttribute("aria-expanded", "true");

        requestAnimationFrame(() => {
          const target = focusLast ? menuItems[menuItems.length - 1] : menuItems[0];
          target.focus();
        });
      };

      const toggleMenu = () => {
        if (menuOpen) {
          closeMenu(false);
          return;
        }

        openMenu(false);
      };

      const closeDialog = (restoreFocus) => {
        if (!dialogOpen) {
          return;
        }

        dialogOpen = false;
        filesBackdrop.hidden = true;
        filesSourcesButton.setAttribute("aria-expanded", "false");
        filesSourcesButton.setAttribute("aria-pressed", "false");
        appShell.inert = false;

        if (restoreFocus && dialogTrigger) {
          dialogTrigger.focus();
        }

        dialogTrigger = null;
      };

      const openDialog = () => {
        if (menuOpen) {
          closeMenu(false);
        }

        dialogOpen = true;
        dialogTrigger = filesSourcesButton;
        filesBackdrop.hidden = false;
        filesSourcesButton.setAttribute("aria-expanded", "true");
        filesSourcesButton.setAttribute("aria-pressed", "true");
        appShell.inert = true;

        requestAnimationFrame(() => {
          closeFilesDialogButton.focus();
        });
      };

      const resetConversation = () => {
        closeMenu(false);
        closeDialog(false);
        conversationTitle.textContent = "Új beszélgetés";
        emptyStateHeading.textContent = "Mire vagy kíváncsi?";
        newChatButton.focus();
      };

      const shareConversation = async () => {
        const shareData = {
          title: document.title,
          text: "Beszélgetés megosztása",
          url: window.location.href
        };

        try {
          if (navigator.share) {
            await navigator.share(shareData);
            return;
          }

          if (navigator.clipboard && window.isSecureContext) {
            await navigator.clipboard.writeText(window.location.href);
            shareChatButton.setAttribute("aria-label", "Csevegés hivatkozása a vágólapra másolva");

            window.setTimeout(() => {
              shareChatButton.setAttribute("aria-label", "Csevegés megosztása");
            }, 2200);

            return;
          }

          shareChatButton.setAttribute("aria-label", "A megosztás nem érhető el");

          window.setTimeout(() => {
            shareChatButton.setAttribute("aria-label", "Csevegés megosztása");
          }, 2200);
        } catch (error) {
          if (error && error.name === "AbortError") {
            return;
          }

          shareChatButton.setAttribute("aria-label", "A megosztás nem sikerült");

          window.setTimeout(() => {
            shareChatButton.setAttribute("aria-label", "Csevegés megosztása");
          }, 2200);
        }
      };

      moreOptionsButton.addEventListener("click", toggleMenu);

      moreOptionsButton.addEventListener("keydown", (event) => {
        if (event.key === "ArrowDown") {
          event.preventDefault();

          if (menuOpen) {
            menuItems[0].focus();
          } else {
            openMenu(false);
          }
        }

        if (event.key === "ArrowUp") {
          event.preventDefault();

          if (menuOpen) {
            menuItems[menuItems.length - 1].focus();
          } else {
            openMenu(true);
          }
        }

        if (event.key === "Escape") {
          closeMenu(true);
        }
      });

      moreOptionsMenu.addEventListener("keydown", (event) => {
        const currentIndex = menuItems.indexOf(document.activeElement);

        if (event.key === "Escape") {
          event.preventDefault();
          closeMenu(true);
          return;
        }

        if (event.key === "ArrowDown") {
          event.preventDefault();
          menuItems[(currentIndex + 1 + menuItems.length) % menuItems.length].focus();
          return;
        }

        if (event.key === "ArrowUp") {
          event.preventDefault();
          menuItems[(currentIndex - 1 + menuItems.length) % menuItems.length].focus();
          return;
        }

        if (event.key === "Home") {
          event.preventDefault();
          menuItems[0].focus();
          return;
        }

        if (event.key === "End") {
          event.preventDefault();
          menuItems[menuItems.length - 1].focus();
          return;
        }

        if (event.key === "Tab") {
          closeMenu(false);
        }
      });

      menuItems.forEach((item) => {
        item.addEventListener("click", () => {
          const action = item.dataset.menuAction;
          closeMenu(false);

          if (action === "rename") {
            const nextTitle = window.prompt("A beszélgetés új neve:", conversationTitle.textContent);

            if (nextTitle && nextTitle.trim()) {
              conversationTitle.textContent = nextTitle.trim();
            }
          }

          if (action === "archive") {
            conversationTitle.textContent = "Archivált beszélgetés";
            emptyStateHeading.textContent = "A beszélgetés archiválva";
          }

          if (action === "theme") {
            setTheme(root.dataset.theme === "dark" ? "light" : "dark");
          }

          moreOptionsButton.focus();
        });
      });

      filesSourcesButton.addEventListener("click", () => {
        if (dialogOpen) {
          closeDialog(true);
        } else {
          openDialog();
        }
      });

      closeFilesDialogButton.addEventListener("click", () => {
        closeDialog(true);
      });

      filesBackdrop.addEventListener("mousedown", (event) => {
        if (event.target === filesBackdrop) {
          closeDialog(true);
        }
      });

      filesDialog.addEventListener("keydown", (event) => {
        if (event.key === "Escape") {
          event.preventDefault();
          closeDialog(true);
          return;
        }

        if (event.key === "Tab") {
          const focusableElements = getFocusableElements(filesDialog);

          if (focusableElements.length === 0) {
            event.preventDefault();
            return;
          }

          const firstElement = focusableElements[0];
          const lastElement = focusableElements[focusableElements.length - 1];

          if (event.shiftKey && document.activeElement === firstElement) {
            event.preventDefault();
            lastElement.focus();
            return;
          }

          if (!event.shiftKey && document.activeElement === lastElement) {
            event.preventDefault();
            firstElement.focus();
          }
        }
      });

      document.addEventListener("pointerdown", (event) => {
        if (menuOpen && !moreOptionsMenu.contains(event.target) && !moreOptionsButton.contains(event.target)) {
          closeMenu(false);
        }
      });

      document.addEventListener("keydown", (event) => {
        if (event.key === "Escape" && menuOpen) {
          closeMenu(true);
        }
      });

      newChatButton.addEventListener("click", resetConversation);
      shareChatButton.addEventListener("click", shareConversation);

      themeToggle.addEventListener("click", () => {
        setTheme(root.dataset.theme === "dark" ? "light" : "dark");
      });

      let storedTheme = null;

      try {
        storedTheme = window.localStorage.getItem("chat-header-theme");
